<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_once dirname(__DIR__,2).'/app/controllers/ApiController.php';
runApi(function(){$current=requireLogin();$repo=new JsonRepository('usuarios');$rows=$repo->all();if(method()==='GET'){requireAdmin();$safe=array_map(fn($u)=>['id'=>$u['id'],'nome'=>$u['nome'],'email'=>$u['email'],'role'=>$u['role'],'ativo'=>$u['ativo']],$rows);jsonResponse(['ok'=>true,'items'=>$safe]);}requireCsrf();$d=inputData();
 if(method()==='PATCH'){$name=cleanText($d['nome']??$current['nome'],100);$email=filter_var(trim((string)($d['email']??$current['email'])),FILTER_VALIDATE_EMAIL);$password=(string)($d['senha']??'');if(!$email)throw new InvalidArgumentException('Informe um e-mail válido.');foreach($rows as &$u)if($u['id']===$current['id']){foreach($rows as $other)if($other['id']!==$u['id']&&$other['email']===strtolower($email))throw new InvalidArgumentException('Este e-mail já está cadastrado.');$u['nome']=$name;$u['email']=strtolower($email);if($password!==''){if(strlen($password)<10)throw new InvalidArgumentException('A senha deve ter pelo menos 10 caracteres.');$u['senha_hash']=password_hash($password,PASSWORD_DEFAULT);}$_SESSION['user']['nome']=$name;$_SESSION['user']['email']=strtolower($email);break;}unset($u);$repo->saveAll($rows);jsonResponse(['ok'=>true,'user'=>$_SESSION['user'],'message'=>'Dados atualizados.']);}
 requireAdmin();if(method()==='POST'){$name=cleanText($d['nome']??'',100);$email=filter_var(trim((string)($d['email']??'')),FILTER_VALIDATE_EMAIL);$password=(string)($d['senha']??'');$role=$d['role']??'usuario';if(!$name||!$email||strlen($password)<10||!in_array($role,['admin','usuario'],true))throw new InvalidArgumentException('Confira nome, e-mail, perfil e senha (mínimo de 10 caracteres).');foreach($rows as $u)if($u['email']===strtolower($email))throw new InvalidArgumentException('E-mail já cadastrado.');$rows[]=['id'=>newId('usr'),'nome'=>$name,'email'=>strtolower($email),'senha_hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role,'ativo'=>true,'criado_em'=>date(DATE_ATOM)];$repo->saveAll($rows);jsonResponse(['ok'=>true,'message'=>'Usuário criado.']);}
 if(method()==='PUT'){$found=false;foreach($rows as &$u)if($u['id']===($d['id']??'')){$u['ativo']=!empty($d['ativo']);$found=true;break;}unset($u);if(!$found)jsonResponse(['ok'=>false,'message'=>'Usuário não encontrado.'],404);$repo->saveAll($rows);jsonResponse(['ok'=>true,'message'=>'Acesso atualizado.']);}
 jsonResponse(['ok'=>false,'message'=>'Método não permitido.'],405);});

